INSERT INTO sdn_aliases (sdn_id, alias, alias_normalized, alias_type) SELECT e.id, v.alias, v.norm, v.typ FROM v JOIN sdn_entries e ON e.uid = v.uid WHERE NOT EXISTS (SELECT 1 FROM sdn_aliases a WHERE a.sdn_id = e.id AND a.alias = v.alias AND a.alias_type IS v.typ);
